    public static class TextGeneration
    {   
    	//note - char and string arrays are all aligned
    	private static readonly char[] _decimal_chars 					= "0123456789".ToCharArray();
		private static readonly char[] _alphabet_chars 					= "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ".ToCharArray();		
		private static readonly char[] _syntax_chars 					= "=+-*%&|^!.?!:;,/<>(){}[]".ToCharArray();		
		private static readonly char[] _edge_case_chars					= { '\u005c', '_', ' ' };
		private static readonly string[] _decimal_replacement_strings 	= { "_0", "_1", "_2", "_3", "_4", "_5", "_6", "_7", "_8", "_9"  };
		private static readonly string[] _alphabet_replacement_strings 	= { "_A", "_B", "_C", "_D", "_E", "_F", "_G", "_H", "_I", "_J", "_K", "_L", "_M", "_N", "_O", "_P", "_Q", "_R", "_S", "_T", "_U", "_V", "_W", "_X", "_Y", "_Z" };		
		private static readonly string[] _edge_case_replacement_strings	= { "_LSLASH", "_ULINE", "_SPACE" };
		private static readonly string[] _syntax_replacement_strings 	= { "_EQUALS", "_PLUS", "_MINUS", "_MUL", "_MOD", "_AND", "_OR", "_XOR", "_NOT", "_PERIOD", "_QUEST", "_EXCL", "_COLON", "_SCOLON", "_COMMA", "_RSLASH", "_LSHIFT", "_RSHIFT", "_LPAREN", "_RPAREN", "_LCURL", "_RCURL", "_LBRACKET", "_RBRACKET" }; 	
					

		private static string _log;

		public static void BitmapCharacterArray()
        {   
        	_log = "";
			
			string render 		= "\nrender_string(characters, length, size_font, color, coordinate_origin, _ColorTarget);\n////\n\n";

			string y_offset 	= "coordinate_origin.y += line_offset;\n\n";

			CharacterArray("uint contract_2(uint x)");
			_log 				+= render;
			_log 				+= y_offset;
			CharacterArray("{");
			_log 				+= render;
			_log 				+= "coordinate_origin.x += tab_offset;\n";
			_log 				+= y_offset;
			CharacterArray("x =  x                      & 0x55555555;");
			_log 				+= render;
			_log 				+= y_offset;
			CharacterArray("x = (x | (x >> 0x00000001)) & 0x33333333;");
			_log 				+= render;
			_log 				+= y_offset;
			CharacterArray("x = (x | (x >> 0x00000002)) & 0x0F0F0F0F;");
			_log 				+= render;
			_log 				+= y_offset;
			CharacterArray("x = (x | (x >> 0x00000004)) & 0x00FF00FF;");
			_log 				+= render;
			_log 				+= y_offset;
			CharacterArray("x = (x | (x >> 0x00000008)) & 0x0000FFFF;");
			_log 				+= render;
			_log 				+= y_offset;
			CharacterArray("return x;");
			_log 				+= render;
			_log 				+= "coordinate_origin.x -= tab_offset;\n";
			_log 				+= y_offset;
			CharacterArray("}");
			_log 				+= render;

        	Debug.Log(_log);			
        }

        public static void CharacterArray(string input_string)
        {   
        	char[] input_chars 			= input_string.ToCharArray();
        	
        	string[] parsed_strings		= new string[input_chars.Length];
			
			bool match  				= false;
			
			////PARSE INPUT
			//edge cases
        	for(int i = 0; i < input_chars.Length; i++)
        	{		
				for(int j = 0; j < _edge_case_chars.Length; j++)
        		{
	        		if(input_chars[i] == _edge_case_chars[j])
	        		{	       
						parsed_strings[i] = _edge_case_replacement_strings[j];
	        			match = true;
	        		}
	        	}
	        }

	        //the rest
			for(int i = 0; i < input_chars.Length; i++)
        	{
        		match 					= false;

        		for(int j = 0; j < _syntax_chars.Length; j++)
        		{
        			if(match == true) break;
        			if(input_chars[i] == _syntax_chars[j])
        			{
        				parsed_strings[i] 	= _syntax_replacement_strings[j];
        				match 				= true;
        			}
				}

        		for(int j = 0; j < _decimal_chars.Length; j++)
        		{
        			if(match == true) break;
        			if(input_chars[i] == _decimal_chars[j])
        			{
        				parsed_strings[i] 	= _decimal_replacement_strings[j];
        				match 				= true;
        			}
				}

        		for(int j = 0; j < _alphabet_replacement_strings.Length; j++)
        		{	
        			if(match == true) break;
        			if(input_chars[i] == _alphabet_chars[j] || input_chars[i] == _alphabet_chars[j+26])
        			{
        				parsed_strings[i] 	= _alphabet_replacement_strings[j];
        				match 				= true;
        				break;
        			}
        		}

        		if(!match)
        		{
        			for(int j = 0; j < _syntax_chars.Length; j++)
	        		{
		        		if(input_chars[i] == _syntax_chars[j])
		        		{							
		        			match = true;
		        			Debug.Log("Syntax : " + _syntax_chars[j]);
		        		}
		        	}

		        	for(int j = 0; j < _edge_case_chars.Length; j++)
	        		{
		        		if(input_chars[i] == _edge_case_chars[j])
		        		{							
		        			match = true;
		        			Debug.Log("Edge Case : " + _edge_case_replacement_strings[j]);
		        		}
		        	}

		        	if(!match)
        			{
        				Debug.LogWarning("Warning : Unrecognized character " + input_chars[i] + " in input string.");
						parsed_strings[i] = "_SPACE";
					}
        		}        		
        	}
        	////END PARSE INPUT

        	////WRITE OUTPUT
        	string output_string 		= "";
        	int odd 					= (parsed_strings.Length & 0x00000001) != 0 ? 1 : 0;
        	int length 					=  parsed_strings.Length/2 + odd;
        	for(int i = 0; i < length; i++)		
			{			
				if(i*2+1 >= parsed_strings.Length)
				{
					output_string 		+= "characters[" + i.ToString().PadLeft(2) + "] = " + parsed_strings[i*2] + ";\n";
				}
				else
				{
					output_string 		+= "characters[" + i.ToString().PadLeft(2) + "] = " 
										+ parsed_strings[i*2] 
										+ " | " 
										+ parsed_strings[i*2+1] 
										+ " << 16;\n";
				}								
			}

			output_string 				+= "length\t\t=" + length + ";";

			output_string 				= "//" + input_string + "\n" + output_string;			
			// Debug.Log(output_string);			
			_log 						+= output_string;
			////END WRITE OUTPUT
        }


        public static void BinaryHexDecimalStrings()
        {    
            string output = "";
        
        	uint[] numerator 	= _numerator;
        	uint[] denominator 	= _denominator;
            
            output += "Rational Coefficients of Probability Distribution Function, 0-9999\n\n";

            output += "Numerator";
            for(int i = 0; i < denominator.Length; i++)
            {
                output += Bitwise.BinaryHexDecimalString(numerator[i]) + "\n";  

                // float d = distribution((float)i+1);
                // float r = -(float)numerator[i]/(float)denominator[i];
                // output +=  d.ToString().PadLeft(16) + "  " + r.ToString().PadLeft(16) + "  " + Mathf.Abs(d-r).ToString().PadLeft(16) + "\n";                    
            }

            
		
			StreamWriter writer 				= new StreamWriter("Assets/Resources/numerator.cginc", false, System.Text.Encoding.UTF8);
			writer.Write(output);
			writer.Close();
			

            Debug.Log(output);
        }

        private static float distribution(float n)
        {
			float x		= (((Mathf.Pow(n, 2.0f)/8.0f)+.5f));	
			float y		= Mathf.Ceil(Mathf.Pow((1.0f/n), 2.0f))-Mathf.Floor(1.0f/Mathf.Pow(3.0f * n, 2.0f));
			return (y/x)-1.0f;
		}

