        public static void DiscreteDistributionFunction()
        {
        	uint[] denominator 	= _denominator;
        	uint[] numerator 	= new uint[denominator.Length];
        	float x 			= 0.0f;
			float y 			= 0.0f;
			
			string log 			= "";
        	for(int n = 0; n < 64; n++)
        	{
        		x		= Mathf.Ceil(((Mathf.Pow(n, 2.0f)/8.0f)+.5f));	
				y		= Mathf.Ceil(Mathf.Pow((1.0f/n), 2.0f))-Mathf.Floor(1.0f/Mathf.Pow(3.0f * n, 2.0f));

				log 	+= x.ToString().PadLeft(8) + " " + y.ToString().PadLeft(8) + " " + distribution(n).ToString().PadLeft(8) + "\n";        		
        	}

        	Debug.Log(log);
        }

